    /// P4: an in-flight compaction is published and cleared again, so the runner can
    /// see it (agent-session.ts:8088-8092 / 8141-8147, 9606-9610 / 9715-9720).
    #[tokio::test(flavor = "multi_thread", worker_threads = 2)]
    async fn compaction_operation_is_published_and_cleared() {
        let agent = ScriptedAgent::new(vec![]);
        let session = test_session(agent);
        assert!(session.compaction_operation.lock().unwrap().is_none());
        let operation = session.begin_compaction_operation();
        assert!(
            session.compaction_operation.lock().unwrap().is_some(),
            "the in-flight compaction is visible to the runner (TS 8598)"
        );
        session.end_compaction_operation(&operation);
        assert!(
            session.compaction_operation.lock().unwrap().is_none(),
            "the owning finally clears the operation (TS 9717-9720)"
        );
        session.dispose_async(Some(false)).await;
    }

    /// REGRESSION (fast): a session slash command must settle the awaiting `prompt`
    /// AND leave the session usable.
    ///
    /// Measured defect: `prompt("/goal status")` never returned. The transcript
    /// already held the `session_slash_command` and `session_slash_command_result`
    /// rows and `is_streaming()` was false, so the handler had finished - the
    /// awaiting call at `prompt_internal_with` (`agent_session.rs:8219`
    /// `wait_for_session_input_idle`) was what never resolved.
    ///
    /// Root cause: `execute_selected_session_command` transitioned a STALE
    /// PUMP-LOCAL SNAPSHOT of the action (a clone captured while it was
    /// `queued`/`selected`) instead of the store's live entry.
    /// `transition_session_action` rejected the illegal `selected -> running` step,
    /// the error was dropped by `let _ =`, and `update_action` then wrote the stale
    /// `selected` lifecycle back over the row the pump had already moved to
    /// `running`. `release_terminal` then refused the still-nonterminal entry
    /// ("Cannot release nonterminal session action"), so a `selected` action stayed
    /// in the store forever: `has_selectable_session_input()` stayed true and the
    /// pump re-selected and re-ran the same command in an infinite loop, so the
    /// session never reached idle and the awaiting `prompt` never resolved.
    ///
    /// TypeScript reference: `_executeSelectedSessionCommand`
    /// (agent-session.ts:6518-6557) transitions the SAME object the store holds
    /// (`ActionStore.selectFirst()` at session-action-store.ts:227-233 returns the
    /// element and `transitionSessionAction` at :107-127 mutates `action.lifecycle`
    /// in place), so a stale write-back cannot happen there.
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn session_command_prompt_settles_and_the_session_stays_usable() {
        let session = test_session_with_credentials().await;

        // A session command must settle promptly instead of parking forever.
        let started = std::time::Instant::now();
        let command = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            session.prompt("/goal status", None),
        )
        .await
        .expect("DEFECT: prompt(\"/goal status\") never returned; the session command wedged the session");
        command.expect("the session command prompt must not reject");
        let command_elapsed = started.elapsed();

        // The action must be gone from the store, not stranded as `selected`.
        assert_eq!(
            session.unfinished_action_count(),
            0,
            "the finished session-command action must be released, not left unfinished (it stayed \"selected\" forever)"
        );
        assert!(
            !session.has_selectable_session_input(),
            "no action may remain selectable after the session command completed, or the pump re-runs it forever"
        );
        // TS 6555 `this._actionStore.releaseTerminal(action)` runs in the `finally`
        // of `_executeSelectedSessionCommand`, so the finished command is REMOVED
        // from the store. Reverting only that release (keeping the live-state
        // transitions) leaves a terminal row behind: the store grows without bound
        // over a long session and its tickets are never deleted.
        assert_eq!(
            session.action_store.lock().unwrap().owned_actions().len(),
            0,
            "the finished session command must be released from the store, not retained as a terminal row (TS 6555)"
        );

        // The session must still be usable for a normal turn.
        let follow_up = tokio::time::timeout(
            std::time::Duration::from_secs(5),
            session.prompt("plain prompt after the session command", None),
        )
        .await
        .expect("DEFECT: a plain prompt after a session command never returned; the session stayed wedged");
        follow_up.expect("the follow-up prompt must not reject");

        assert!(
            command_elapsed < std::time::Duration::from_secs(5),
            "the session command must settle promptly, took {command_elapsed:?}"
        );
        session.dispose_async(Some(false)).await;
    }

    // ---------------------------------------------------------------------------
    // T03: session <-> ipython kernel provisioner ownership (agent-session.ts:10061-10102)
    // ---------------------------------------------------------------------------

    use crate::core::extensions::types::ExtensionContext as ExtensionContextTrait;
    use crate::core::extensions::types::ModelRegistry as ModelRegistryTrait;
    use crate::core::extensions::types::ReadonlySessionManager as ReadonlySessionManagerTrait;
    use crate::core::kernel::shared::{
        ExecuteResult, ExecuteStatus, KernelError, KernelStartOptions,
    };
    use crate::core::tools::ipython::KernelClient;

    /// Global serialization for tests that install the kernel-client factory
    /// override (process-global state; parallel tests must not race on it).
    static KERNEL_FACTORY_TEST_LOCK: Mutex<()> = Mutex::new(());

    /// TS `KernelClient` fake: records every lifecycle call the provisioner and
    /// the tool make against it.
    struct RecordingKernelClient {
        id: u64,
        events: Arc<Mutex<Vec<String>>>,
        alive: AtomicBool,
    }

    impl KernelClient for RecordingKernelClient {
        fn is_running(&self) -> bool {
            self.alive.load(Ordering::SeqCst)
        }
        fn is_defunct(&self) -> bool {
            false
        }
        fn start(
            &self,
            _options: KernelStartOptions,
        ) -> futures::future::BoxFuture<'static, Result<(), KernelError>> {
            self.events
                .lock()
                .unwrap()
                .push(format!("start:{}", self.id));
            Box::pin(async { Ok(()) })
        }
        fn execute(
            &self,
            code: &str,
            _signal: Option<crate::core::kernel::shared::AbortSignal>,
            _on_stream: Option<
                Arc<dyn Fn(&str, crate::core::kernel::shared::StreamName) + Send + Sync>,
            >,
        ) -> futures::future::BoxFuture<'static, Result<ExecuteResult, KernelError>> {
            self.events
                .lock()
                .unwrap()
                .push(format!("execute:{}:{}", self.id, code));
            Box::pin(async move {
                Ok(ExecuteResult {
                    stdout: String::new(),
                    stderr: String::new(),
                    result: None,
                    diffs: None,
                    attachments: None,
                    sent_agent_messages: None,
                    background_output: None,
                    status: ExecuteStatus::Ok,
                    error: None,
                    execution_reports: None,
                    duration_ms: 0.0,
                })
            })
        }
        fn restore_state(
            &self,
        ) -> futures::future::BoxFuture<
            'static,
            Result<Option<crate::core::kernel::state_snapshot::RestoreResult>, KernelError>,
        > {
            self.events
                .lock()
                .unwrap()
                .push(format!("restore:{}", self.id));
            Box::pin(async { Ok(None) })
        }
        fn shutdown(
            &self,
            snapshot: bool,
            drain_host_requests: bool,
        ) -> futures::future::BoxFuture<'static, Result<(), KernelError>> {
            self.alive.store(false, Ordering::SeqCst);
            self.events.lock().unwrap().push(format!(
                "shutdown:{}:snapshot={}:drain={}",
                self.id, snapshot, drain_host_requests
            ));
            Box::pin(async { Ok(()) })
        }
        fn kill(&self) -> futures::future::BoxFuture<'static, Result<(), KernelError>> {
            self.alive.store(false, Ordering::SeqCst);
            self.events
                .lock()
                .unwrap()
                .push(format!("kill:{}", self.id));
            Box::pin(async { Ok(()) })
        }
        fn prune_oversized_variables(
            &self,
        ) -> futures::future::BoxFuture<
            'static,
            Result<Option<crate::core::tools::ipython::PruneResult>, KernelError>,
        > {
            Box::pin(async { Ok(None) })
        }
        fn list_namespace_names(
            &self,
            _signal: Option<crate::core::kernel::shared::AbortSignal>,
        ) -> futures::future::BoxFuture<'static, Result<Option<Vec<String>>, KernelError>> {
            Box::pin(async { Ok(Some(Vec::new())) })
        }
    }

    fn recording_kernel_factory() -> (
        crate::core::tools::ipython::KernelClientFactory,
        Arc<Mutex<Vec<String>>>,
    ) {
        let (factory, events, _options) = recording_kernel_factory_with_options();
        (factory, events)
    }

    /// Same as [`recording_kernel_factory`], but also records every
    /// `KernelManagerOptions` snapshot the provisioner hands the factory.
    fn recording_kernel_factory_with_options() -> (
        crate::core::tools::ipython::KernelClientFactory,
        Arc<Mutex<Vec<String>>>,
        Arc<Mutex<Vec<crate::core::kernel::shared::KernelManagerOptions>>>,
    ) {
        let events: Arc<Mutex<Vec<String>>> = Arc::new(Mutex::new(Vec::new()));
        let factory_events = events.clone();
        let recorded_options: Arc<Mutex<Vec<crate::core::kernel::shared::KernelManagerOptions>>> =
            Arc::new(Mutex::new(Vec::new()));
        let recorded = recorded_options.clone();
        let next_id = Arc::new(AtomicU64::new(1));
        let factory: crate::core::tools::ipython::KernelClientFactory = Arc::new(move |options| {
            let id = next_id.fetch_add(1, Ordering::SeqCst);
            factory_events
                .lock()
                .unwrap()
                .push(format!("create:{}", id));
            recorded.lock().unwrap().push(options.clone());
            Arc::new(RecordingKernelClient {
                id,
                events: factory_events.clone(),
                alive: AtomicBool::new(true),
            })
        });
        (factory, events, recorded_options)
    }

